output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisles",
    "text": "Shopping carts are prohibited in one-cell-wide aisles between opposing shelves.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_narrow_aisle_with_cart",
    "text": "A shopper must not move into a single-file shelf aisle while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "narrow_shelf_items_on_foot",
    "text": "Items taken from shelves inside single-file aisles must be collected on foot rather than with a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {
        "shelfInteractionInSingleFileAisle": {
          "pre": {
            "and": [
              "INTERACT",
              "singleFileShelfAisle"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "shelfInteractionInSingleFileAisle"
        ]
      }
    }
  },
  {
    "id": "park_only_in_wide_staging_area",
    "text": "If a shopper parks or releases a cart, they must do so only in a wide non-shelf staging area.",
    "abstraction": {
      "state_properties": {
        "wideStagingArea": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "wideStagingArea"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking a cart for an aisle excursion, the shopper is obliged to retrieve a cart before the trip ends.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "cart_free_narrow_excursion_must_return_to_cart",
    "text": "A shopper who enters a single-file shelf aisle without a cart must later return to cart possession.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileOnFoot",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "keep_cart_for_wide_shelf_pickups",
    "text": "When a shelf item is reachable from a wide aisle, the shopper should keep the cart while interacting with that shelf.",
    "abstraction": {
      "state_properties": {
        "wideShelfAccess": {
          "and": [
            "adjShelf",
            {
              "ge": [
                "freeWidthH",
                6
              ]
            }
          ]
        }
      },
      "events": {
        "wideShelfInteraction": {
          "pre": {
            "and": [
              "INTERACT",
              "wideShelfAccess"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideShelfInteraction",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_between_opposing_shelves",
    "text": "Carts are prohibited in cells flanked by shelves on both sides, regardless of the exact location.",
    "abstraction": {
      "state_properties": {
        "betweenOpposingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "betweenOpposingShelves"
        ]
      }
    }
  }
]
